using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Text;using CityForge.CameraSystem;using UnityEngine;
namespace CityForge.World {
public sealed class MountainAcceptance:MonoBehaviour {
public const string Output="/Users/joelinstrum/Documents/Codex/2026-10-12/begin-from-this-handoff-and-start/outputs/";
public static bool Running;StringBuilder report=new();string reportPath;
static PrototypeRegionView View=>FindFirstObjectByType<PrototypeRegionView>();
[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){if(!Application.isEditor&&Array.Exists(System.Environment.GetCommandLineArgs(),a=>a=="--mountain-acceptance"))new GameObject("Mountain acceptance").AddComponent<MountainAcceptance>();}
void Start(){Application.runInBackground=true;Running=true;reportPath=Output+"Mountain-Five-Steps-"+(Application.isEditor?"Editor":"Player")+"-Checks.txt";StartCoroutine(Protect(Check()));}
IEnumerator Protect(IEnumerator routine){var stack=new Stack<IEnumerator>();stack.Push(routine);while(stack.Count>0){bool next=false;object value=null;Exception error=null;try{next=stack.Peek().MoveNext();if(next)value=stack.Peek().Current;}catch(Exception e){error=e;}if(error!=null){Line("FAILED: "+error);if(View){View.GetComponentInChildren<CityForgeCameraController>().enabled=true;View.ApprovedDistrict.SetFramePacing60(true);}Running=false;if(!Application.isEditor)Application.Quit(1);yield break;}if(!next){(stack.Pop() as IDisposable)?.Dispose();continue;}if(value is IEnumerator child){stack.Push(child);continue;}yield return value;}Running=false;if(!Application.isEditor)Application.Quit(0);else Destroy(gameObject);}
void Line(string s){report.AppendLine(s);File.WriteAllText(reportPath,report.ToString());Debug.Log(s);}
static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
static IEnumerator Wait(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}
static IEnumerator Open(SavedRegionSnapshot saved){if(View)View.ReturnToMenu();yield return null;yield return null;yield return Resources.UnloadUnusedAssets();PrototypeRegionView.Open(saved.info.name,FindFirstObjectByType<Canvas>(),snapshot:saved);View.ApprovedDistrict.SetTreesEnabled(true);View.ApprovedDistrict.SetSmallPlantsEnabled(true);yield return Wait(1);}
IEnumerator Capture(string name){yield return new WaitForEndOfFrame();var image=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);image.Apply();File.WriteAllBytes(Output+name+".png",image.EncodeToPNG());Destroy(image);}
static ulong Heights(PrototypeRegionData data){ulong hash=14695981039346656037UL;foreach(float value in data.Heights){hash^=BitConverter.ToUInt32(BitConverter.GetBytes(value),0);hash*=1099511628211UL;}return hash;}
IEnumerator Check(){
Line($"Mountain five-step acceptance: {(Application.isEditor?"Editor":"macOS standalone")}; Unity {Application.unityVersion}; {SystemInfo.graphicsDeviceName}; {Screen.width}x{Screen.height}.");
var saved=Application.isEditor?SavedRegionStore.Load(Path.Combine(SavedRegionStore.DirectoryPath,HillsMountainTestRegion.Id+".cfregion")):SavedRegionStore.Load(Output+"Hills-And-Mountain-Test.cfregion");
if(saved.meadow==null||saved.meadow.version!=105){var timer=System.Diagnostics.Stopwatch.StartNew();saved=HillsMountainTestRegion.Generate(saved.info.seed);Line($"Mountain recipe and baked MapMagic erosion: {timer.ElapsedMilliseconds}ms.");}
yield return Open(saved);var land=View.ApprovedDistrict;var rocks=land.GetComponent<MountainRockRenderer>();
Require(land.Side==1024&&land.DisplayTerrain.terrainData.size.y==360&&land.Baseline.layers.Length==8,"Terrain dimensions/layers");
Line($"Mountain placements: outcrops={rocks?.OutcropCount}; scree={rocks?.ScreeCount}.");Require(rocks&&rocks.OutcropCount==0&&rocks.ScreeCount>10,"Large outcrops remain or smaller scree placement is missing");Require(!land.Water&&View.Data.WaterBodies.Length==0,"Dry mountain grew water");float grade=MountainRoad.MaximumGrade(land);Require(grade<=.175f,"Road exceeds grade limit");
Line($"PASS 1024m district, 360m height range, 8 layers, dry terrain. {land.FullTreeCount} trees; {rocks.OutcropCount} outcrops; {rocks.ScreeCount} loose stones; road {land.Road.Count} samples, max grade {grade*100:F2}%.");Line("Generation: "+land.GenerationTimings);
ulong heights=Heights(View.Data),fingerprint=rocks.Fingerprint;int treeCount=land.FullTreeCount;var road=land.Road.ToArray();var snapshot=SavedRegionStore.Capture(View);string roundtrip=Output+"Mountain-"+(Application.isEditor?"Editor":"Player")+"-Roundtrip.cfregion";SavedRegionStore.Write(snapshot,roundtrip);
yield return Open(SavedRegionStore.Load(roundtrip));land=View.ApprovedDistrict;rocks=land.GetComponent<MountainRockRenderer>();Require(land.UsedSavedTerrain&&Heights(View.Data)==heights&&rocks.Fingerprint==fingerprint&&land.FullTreeCount==treeCount&&land.Road.SequenceEqual(road),"Reload changes terrain, road, rocks, trees, or discards cache");
Line($"PASS save/reload retains heightfield {heights:X16}, rocks {fingerprint:X16}, trees and road; canonical cache restored.");
var rig=View.GetComponentInChildren<CityForgeCameraController>();var original=new RegionCameraState{focus=new Vector3(500,75,510),pitch=35.26439f,yaw=315,distance=700,size=640,zoom=5};rig.enabled=false;land.SetFramePacing60(false);
for(int zoom=0;zoom<=5;zoom++){
rig.RestoreRegionState(original);rig.SetZoomLevel(zoom);var pose=rig.CaptureRegionState();yield return Wait(2);var samples=new List<float>();float start=Time.realtimeSinceStartup;
while(Time.realtimeSinceStartup-start<4){float t=Time.realtimeSinceStartup-start;pose.focus=original.focus+new Vector3(Mathf.Sin(t)*35,0,Mathf.Sin(t*.7f)*25);pose.yaw=315+t*20;rig.RestoreRegionState(pose);var camera=rig.GetComponent<Camera>();var p=new Vector2(camera.transform.position.x,camera.transform.position.z);Require(!land.Contains(p)||camera.transform.position.y>land.Height(p)+3,"Camera entered terrain");yield return null;samples.Add(Time.unscaledDeltaTime*1000);}
samples.Sort();Line($"Zoom {zoom}; pan/rotate: mean={samples.Average():F2}ms; p95={samples[(int)(samples.Count*.95)]:F2}ms; max={samples.Last():F2}ms; >25ms={samples.Count(s=>s>25)*100f/samples.Count:F2}%.");
rig.RestoreRegionState(original);rig.SetZoomLevel(zoom);yield return Wait(.25f);if(zoom>=2)yield return Capture("Mountain-Five-Steps-"+(Application.isEditor?"Editor":"Player")+"-Zoom"+zoom);
}
// Inspect both mountain slopes and the valley, with a complete yaw sweep.
foreach(var focus in new[]{new Vector3(180,230,790),new Vector3(750,250,780),new Vector3(370,65,420)}){
var pose=new RegionCameraState{focus=focus,pitch=original.pitch,yaw=original.yaw,distance=original.distance,size=160,zoom=3};for(int yaw=0;yaw<360;yaw+=15){pose.yaw=yaw;rig.RestoreRegionState(pose);yield return null;var camera=rig.GetComponent<Camera>();var p=new Vector2(camera.transform.position.x,camera.transform.position.z);Require(!land.Contains(p)||camera.transform.position.y>land.Height(p)+3,"Yaw camera entered mountain");}}
Line("PASS six zoom levels with pan/rotation and 360-degree sweeps at both peaks and valley; camera stays above terrain.");
rig.RestoreRegionState(original);rig.enabled=true;land.SetFramePacing60(true);View.ShowOverview();yield return null;yield return null;Require(!FindObjectsByType<MountainRockRenderer>(FindObjectsSortMode.None).Any(),"Mountain batches leaked on overview");Require(Resources.FindObjectsOfTypeAll<Material>().Count(m=>m.name.StartsWith("Mountain rock surface"))==6,"Overview grew duplicate mountain materials");View.EnterDistrict(3);yield return Wait(1);land=View.ApprovedDistrict;Require(land.GetComponent<MountainRockRenderer>().Fingerprint==fingerprint&&MountainRoad.MaximumGrade(land)<=.175f,"Reentry changed mountain detail or road");
snapshot=SavedRegionStore.Capture(View);View.ReturnToMenu();yield return Wait(.5f);Require(!FindObjectsByType<MountainRockRenderer>(FindObjectsInactive.Include,FindObjectsSortMode.None).Any()&&!Resources.FindObjectsOfTypeAll<Material>().Any(m=>m.name.StartsWith("Mountain rock surface")),"Mountain resources leaked after region exit");yield return Open(snapshot);land=View.ApprovedDistrict;
rig=View.GetComponentInChildren<CityForgeCameraController>();rig.RestoreRegionState(original);rig.SetZoomLevel(5);land.SetTreesEnabled(true);land.SetSmallPlantsEnabled(true);land.SetFramePacing60(true);snapshot=SavedRegionStore.Capture(View);if(Application.isEditor){SavedRegionStore.Save(snapshot);SavedRegionStore.Write(snapshot,Output+"Hills-And-Mountain-Test.cfregion");}
Line("PASS overview suspends rock drawing without duplicate materials; district reentry retains seeded detail; region exit releases rock renderers and owned materials. COMPLETE.");
}
}}
